 /** Shrinks a group of labels together until the longest word fits, so text wraps at spaces and never mid-word. */
 void fit(int avail,TextView... labels){float k=1;for(TextView t:labels)for(String w:t.getText().toString().split("\\s+"))k=Math.min(k,avail/Math.max(1f,t.getPaint().measureText(w)*1.06f));if(k<1)for(TextView t:labels)t.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,(float)Math.floor(t.getTextSize()*k));}
